38	function updateMarkerLayout(
39	    mpData: SeriesData<MarkPointModel>,
40	    seriesModel: SeriesModel,
41	    api: ExtensionAPI
42	) {
43	    const coordSys = seriesModel.coordinateSystem;
44	    mpData.each(function (idx: number) {
45	        const itemModel = mpData.getItemModel<MarkPointDataItemOption>(idx);
46	        let point;
47	        const xPx = numberUtil.parsePercent(itemModel.get('x'), api.getWidth());
48	        const yPx = numberUtil.parsePercent(itemModel.get('y'), api.getHeight());
49	        if (!isNaN(xPx) && !isNaN(yPx)) {
50	            point = [xPx, yPx];
51	        }
52	        // Chart like bar may have there own marker positioning logic
53	        else if (seriesModel.getMarkerPosition) {
54	            // Use the getMarkerPosition
55	            point = seriesModel.getMarkerPosition(
56	                mpData.getValues(mpData.dimensions, idx)
57	            );
58	        }
59	        else if (coordSys) {
60	            const x = mpData.get(coordSys.dimensions[0], idx);
61	            const y = mpData.get(coordSys.dimensions[1], idx);
62	            point = coordSys.dataToPoint([x, y]);
63	        }
64	
65	        // Use x, y if has any
66	        if (!isNaN(xPx)) {
67	            point[0] = xPx;
68	        }
69	        if (!isNaN(yPx)) {
70	            point[1] = yPx;
71	        }
72	
73	        mpData.setItemLayout(idx, point);
74	    });
75	}
76	
77	class MarkPointView extends MarkerView {
78	
79	    static type = 'markPoint';
80	    type = MarkPointView.type;
81	
82	    markerGroupMap: HashMap<SymbolDraw>;
83	
84	    updateTransform(markPointModel: MarkPointModel, ecModel: GlobalModel, api: ExtensionAPI) {
85	        ecModel.eachSeries(function (seriesModel) {
86	            const mpModel = MarkerModel.getMarkerModelFromSeries(seriesModel, 'markPoint') as MarkPointModel;
87	            if (mpModel) {
88	                updateMarkerLayout(
89	                    mpModel.getData(),
90	                    seriesModel, api
91	                );
92	                this.markerGroupMap.get(seriesModel.id).updateLayout();
93	            }
94	        }, this);
95	    }
96	
97	    renderSeries(
98	        seriesModel: SeriesModel,
99	        mpModel: MarkPointModel,
100	        ecModel: GlobalModel,
101	        api: ExtensionAPI
102	    ) {
103	        const coordSys = seriesModel.coordinateSystem;
104	        const seriesId = seriesModel.id;
105	        const seriesData = seriesModel.getData();
106	
107	        const symbolDrawMap = this.markerGroupMap;
108	        const symbolDraw = symbolDrawMap.get(seriesId)
109	            || symbolDrawMap.set(seriesId, new SymbolDraw());
110	
111	        const mpData = createData(coordSys, seriesModel, mpModel);
112	
113	        // FIXME
114	        mpModel.setData(mpData);
115	
116	        updateMarkerLayout(mpModel.getData(), seriesModel, api);
117	
118	        mpData.each(function (idx) {
119	            const itemModel = mpData.getItemModel<MarkPointDataItemOption>(idx);
120	            let symbol = itemModel.getShallow('symbol');
121	            let symbolSize = itemModel.getShallow('symbolSize');
122	            let symbolRotate = itemModel.getShallow('symbolRotate');
123	            let symbolOffset = itemModel.getShallow('symbolOffset');
124	            const symbolKeepAspect = itemModel.getShallow('symbolKeepAspect');
125	
126	            // TODO: refactor needed: single data item should not support callback function
127	            if (isFunction(symbol) || isFunction(symbolSize) || isFunction(symbolRotate) || isFunction(symbolOffset)) {
128	                const rawIdx = mpModel.getRawValue(idx);
129	                const dataParams = mpModel.getDataParams(idx);
130	                if (isFunction(symbol)) {
131	                    symbol = symbol(rawIdx, dataParams);
132	                }
133	                if (isFunction(symbolSize)) {
134	                    // FIXME 这里不兼容 ECharts 2.x，2.x 貌似参数是整个数据？
135	                    symbolSize = symbolSize(rawIdx, dataParams);
136	                }
137	                if (isFunction(symbolRotate)) {
138	                    symbolRotate = symbolRotate(rawIdx, dataParams);
139	                }
140	                if (isFunction(symbolOffset)) {
141	                    symbolOffset = symbolOffset(rawIdx, dataParams);
142	                }
143	            }
144	
145	            const style = itemModel.getModel('itemStyle').getItemStyle();
146	            const color = getVisualFromData(seriesData, 'color') as ZRColor;
147	            if (!style.fill) {
148	                style.fill = color;
149	            }
150	
151	            mpData.setItemVisual(idx, {
152	                symbol: symbol,
153	                symbolSize: symbolSize,
154	                symbolRotate: symbolRotate,
155	                symbolOffset: symbolOffset,
156	                symbolKeepAspect: symbolKeepAspect,
157	                style
158	            });
159	        });
160	
161	        // TODO Text are wrong
162	        symbolDraw.updateData(mpData);
163	        this.group.add(symbolDraw.group);
164	
165	        // Set host model for tooltip
166	        // FIXME
167	        mpData.eachItemGraphicEl(function (el) {
168	            el.traverse(function (child) {
169	                getECData(child).dataModel = mpModel;
170	            });
171	        });
172	
173	        this.markKeep(symbolDraw);
174	
175	        symbolDraw.group.silent = mpModel.get('silent') || seriesModel.get('silent');
176	    }
177	}
178	
179	function createData(
180	    coordSys: CoordinateSystem,
181	    seriesModel: SeriesModel,
182	    mpModel: MarkPointModel
183	) {
184	    let coordDimsInfos: SeriesDimensionDefine[];
185	    if (coordSys) {
186	        coordDimsInfos = map(coordSys && coordSys.dimensions, function (coordDim) {
187	            const info = seriesModel.getData().getDimensionInfo(
188	                seriesModel.getData().mapDimension(coordDim)
189	            ) || {};
190	            // In map series data don't have lng and lat dimension. Fallback to same with coordSys
191	            return extend(extend({}, info), {
192	                name: coordDim,
193	                // DON'T use ordinalMeta to parse and collect ordinal.
194	                ordinalMeta: null
195	            });
196	        });
197	    }
198	    else {
199	        coordDimsInfos = [{
200	            name: 'value',
201	            type: 'float'
202	        }];
203	    }
204	
205	    const mpData = new SeriesData(coordDimsInfos, mpModel);
206	    let dataOpt = map(mpModel.get('data'), curry(
207	            markerHelper.dataTransform, seriesModel
208	        ));
209	    if (coordSys) {
210	        dataOpt = filter(
211	            dataOpt, curry(markerHelper.dataFilter, coordSys)
212	        );
213	    }
214	
215	    const dimValueGetter = markerHelper.createMarkerDimValueGetter(!!coordSys, coordDimsInfos);
216	    mpData.initData(dataOpt, null, dimValueGetter);
217	
218	    return mpData;
219	}
220	
221	export default MarkPointView;
