20	import * as numberUtil from '../../util/number';
21	import {isDimensionStacked} from '../../data/helper/dataStackHelper';
22	import SeriesModel from '../../model/Series';
23	import SeriesData from '../../data/SeriesData';
24	import { MarkerStatisticType, MarkerPositionOption } from './MarkerModel';
25	import { indexOf, curry, clone, isArray } from 'zrender/src/core/util';
26	import Axis from '../../coord/Axis';
27	import { CoordinateSystem } from '../../coord/CoordinateSystem';
28	import { ScaleDataValue, ParsedValue, DimensionLoose, DimensionName } from '../../util/types';
29	import { parseDataValue } from '../../data/helper/dataValueHelper';
30	import SeriesDimensionDefine from '../../data/SeriesDimensionDefine';
31	
32	interface MarkerAxisInfo {
33	    valueDataDim: DimensionName
34	    valueAxis: Axis
35	    baseAxis: Axis
36	    baseDataDim: DimensionName
37	}
38	
39	export type MarkerDimValueGetter<TMarkerItemOption> = (
40	    item: TMarkerItemOption,
41	    dimName: string,
42	    dataIndex: number,
43	    dimIndex: number
44	) => ParsedValue;
45	
46	function hasXOrY(item: MarkerPositionOption) {
47	    return !(isNaN(parseFloat(item.x as string)) && isNaN(parseFloat(item.y as string)));
48	}
49	
50	function hasXAndY(item: MarkerPositionOption) {
51	    return !isNaN(parseFloat(item.x as string)) && !isNaN(parseFloat(item.y as string));
52	}
53	
54	function markerTypeCalculatorWithExtent(
55	    markerType: MarkerStatisticType,
56	    data: SeriesData,
57	    otherDataDim: string,
58	    targetDataDim: string,
59	    otherCoordIndex: number,
60	    targetCoordIndex: number
61	): [ParsedValue[], ParsedValue] {
62	    const coordArr: ParsedValue[] = [];
63	
64	    const stacked = isDimensionStacked(data, targetDataDim /* , otherDataDim */);
65	    const calcDataDim = stacked
66	        ? data.getCalculationInfo('stackResultDimension')
67	        : targetDataDim;
68	
69	    const value = numCalculate(data, calcDataDim, markerType);
70	
71	    const dataIndex = data.indicesOfNearest(calcDataDim, value)[0];
72	    coordArr[otherCoordIndex] = data.get(otherDataDim, dataIndex);
73	    coordArr[targetCoordIndex] = data.get(calcDataDim, dataIndex);
74	    const coordArrValue = data.get(targetDataDim, dataIndex);
75	    // Make it simple, do not visit all stacked value to count precision.
76	    let precision = numberUtil.getPrecision(data.get(targetDataDim, dataIndex));
77	    precision = Math.min(precision, 20);
78	    if (precision >= 0) {
79	        coordArr[targetCoordIndex] = +(coordArr[targetCoordIndex] as number).toFixed(precision);
80	    }
81	
82	    return [coordArr, coordArrValue];
83	}
84	
85	// TODO Specified percent
86	const markerTypeCalculator = {
87	    min: curry(markerTypeCalculatorWithExtent, 'min'),
88	    max: curry(markerTypeCalculatorWithExtent, 'max'),
89	    average: curry(markerTypeCalculatorWithExtent, 'average'),
90	    median: curry(markerTypeCalculatorWithExtent, 'median')
91	};
92	
93	/**
94	 * Transform markPoint data item to format used in List by do the following
95	 * 1. Calculate statistic like `max`, `min`, `average`
96	 * 2. Convert `item.xAxis`, `item.yAxis` to `item.coord` array
97	 */
98	export function dataTransform(
99	    seriesModel: SeriesModel,
100	    item: MarkerPositionOption
101	) {
102	    if (!item) {
103	        return;
104	    }
105	
106	    const data = seriesModel.getData();
107	    const coordSys = seriesModel.coordinateSystem;
108	    const dims = coordSys && coordSys.dimensions;
109	
110	    // 1. If not specify the position with pixel directly
111	    // 2. If `coord` is not a data array. Which uses `xAxis`,
112	    // `yAxis` to specify the coord on each dimension
113	
114	    // parseFloat first because item.x and item.y can be percent string like '20%'
115	    if (!hasXAndY(item) && !isArray(item.coord) && isArray(dims)) {
116	        const axisInfo = getAxisInfo(item, data, coordSys, seriesModel);
117	
118	        // Clone the option
119	        // Transform the properties xAxis, yAxis, radiusAxis, angleAxis, geoCoord to value
120	        item = clone(item);
121	
122	        if (item.type
123	            && markerTypeCalculator[item.type]
124	            && axisInfo.baseAxis && axisInfo.valueAxis
125	        ) {
126	            const otherCoordIndex = indexOf(dims, axisInfo.baseAxis.dim);
127	            const targetCoordIndex = indexOf(dims, axisInfo.valueAxis.dim);
128	
129	            const coordInfo = markerTypeCalculator[item.type](
130	                data, axisInfo.baseDataDim, axisInfo.valueDataDim,
131	                otherCoordIndex, targetCoordIndex
132	            );
133	            item.coord = coordInfo[0];
134	            // Force to use the value of calculated value.
135	            // let item use the value without stack.
136	            item.value = coordInfo[1];
137	        }
138	        else {
139	            // FIXME Only has one of xAxis and yAxis.
140	            item.coord = [
141	                item.xAxis != null ? item.xAxis : item.radiusAxis,
142	                item.yAxis != null ? item.yAxis : item.angleAxis
143	            ];
144	        }
145	    }
146	    // x y is provided
147	    if (item.coord == null || !isArray(dims)) {
148	        item.coord = [];
149	    }
150	    else {
151	        // Each coord support max, min, average
152	        const coord = item.coord;
153	        for (let i = 0; i < 2; i++) {
154	            if (markerTypeCalculator[coord[i] as MarkerStatisticType]) {
155	                coord[i] = numCalculate(data, data.mapDimension(dims[i]), coord[i] as MarkerStatisticType);
156	            }
157	        }
158	    }
159	    return item;
160	}
161	
162	export function getAxisInfo(
163	    item: MarkerPositionOption,
164	    data: SeriesData,
165	    coordSys: CoordinateSystem,
166	    seriesModel: SeriesModel
167	) {
168	    const ret = {} as MarkerAxisInfo;
169	
170	    if (item.valueIndex != null || item.valueDim != null) {
171	        ret.valueDataDim = item.valueIndex != null
172	            ? data.getDimension(item.valueIndex) : item.valueDim;
173	        ret.valueAxis = coordSys.getAxis(dataDimToCoordDim(seriesModel, ret.valueDataDim));
174	        ret.baseAxis = coordSys.getOtherAxis(ret.valueAxis);
175	        ret.baseDataDim = data.mapDimension(ret.baseAxis.dim);
176	    }
177	    else {
178	        ret.baseAxis = seriesModel.getBaseAxis();
179	        ret.valueAxis = coordSys.getOtherAxis(ret.baseAxis);
180	        ret.baseDataDim = data.mapDimension(ret.baseAxis.dim);
181	        ret.valueDataDim = data.mapDimension(ret.valueAxis.dim);
182	    }
183	
184	    return ret;
185	}
186	
187	function dataDimToCoordDim(seriesModel: SeriesModel, dataDim: DimensionLoose): DimensionName {
188	    const dimItem = seriesModel.getData().getDimensionInfo(dataDim);
189	    return dimItem && dimItem.coordDim;
190	}
191	
192	/**
193	 * Filter data which is out of coordinateSystem range
194	 * [dataFilter description]
195	 */
196	export function dataFilter(
197	    // Currently only polar and cartesian has containData.
198	    coordSys: CoordinateSystem & {
199	        containData?(data: ScaleDataValue[]): boolean
200	    },
201	    item: MarkerPositionOption
202	) {
203	    // Always return true if there is no coordSys
204	    return (coordSys && coordSys.containData && item.coord && !hasXOrY(item))
205	        ? coordSys.containData(item.coord) : true;
206	}
207	
208	export function zoneFilter(
209	    // Currently only polar and cartesian has containData.
210	    coordSys: CoordinateSystem & {
211	        containZone?(data1: ScaleDataValue[], data2: ScaleDataValue[]): boolean
212	    },
213	    item1: MarkerPositionOption,
214	    item2: MarkerPositionOption
215	) {
216	    // Always return true if there is no coordSys
217	    return (coordSys && coordSys.containZone && item1.coord && item2.coord && !hasXOrY(item1) && !hasXOrY(item2))
218	        ? coordSys.containZone(item1.coord, item2.coord) : true;
219	}
220	
221	export function createMarkerDimValueGetter(
222	    inCoordSys: boolean,
223	    dims: SeriesDimensionDefine[]
224	): MarkerDimValueGetter<MarkerPositionOption> {
225	    return inCoordSys
226	        ? function (item, dimName, dataIndex, dimIndex) {
227	            const rawVal = dimIndex < 2
228	                // x, y, radius, angle
229	                ? (item.coord && item.coord[dimIndex])
230	                : item.value;
231	            return parseDataValue(rawVal, dims[dimIndex]);
232	        }
233	        : function (item, dimName, dataIndex, dimIndex) {
234	            return parseDataValue(item.value, dims[dimIndex]);
235	        };
236	}
237	
238	export function numCalculate(
239	    data: SeriesData,
240	    valueDataDim: string,
241	    type: MarkerStatisticType
242	) {
243	    if (type === 'average') {
244	        let sum = 0;
245	        let count = 0;
246	        data.each(valueDataDim, function (val: number, idx) {
247	            if (!isNaN(val)) {
248	                sum += val;
249	                count++;
250	            }
251	        });
252	        return sum / count;
253	    }
254	    else if (type === 'median') {
255	        return data.getMedian(valueDataDim);
256	    }
257	    else {
258	        // max & min
259	        return data.getDataExtent(valueDataDim)[type === 'max' ? 1 : 0];
260	    }
261	}
