38	
39	function fillLabel(opt: DisplayStateHostOption) {
40	    defaultEmphasis(opt, 'label', ['show']);
41	}
42	
43	export type MarkerStatisticType = 'average' | 'min' | 'max' | 'median';
44	
45	/**
46	 * Option to specify where to put the marker.
47	 */
48	export interface MarkerPositionOption {
49	    // Priority: x/y > coord(xAxis, yAxis) > type
50	
51	    // Absolute position, px or percent string
52	    x?: number | string
53	    y?: number | string
54	
55	    /**
56	     * Coord on any coordinate system
57	     */
58	    coord?: (ScaleDataValue | MarkerStatisticType)[]
59	
60	    // On cartesian coordinate system
61	    xAxis?: ScaleDataValue
62	    yAxis?: ScaleDataValue
63	
64	    // On polar coordinate system
65	    radiusAxis?: ScaleDataValue
66	    angleAxis?: ScaleDataValue
67	
68	    // Use statistic method
69	    type?: MarkerStatisticType
70	    /**
71	     * When using statistic method with type.
72	     * valueIndex and valueDim can be specify which dim the statistic is used on.
73	     */
74	    valueIndex?: number
75	    valueDim?: string
76	
77	
78	    /**
79	     * Value to be displayed as label. Totally optional
80	     */
81	    value?: string | number
82	}
83	
84	export interface MarkerOption extends ComponentOption, AnimationOptionMixin {
85	
86	    silent?: boolean
87	
88	    data?: unknown[]
89	
90	    tooltip?: CommonTooltipOption<unknown> & {
91	        trigger?: 'item' | 'axis' | boolean | 'none'
92	    }
93	}
94	
95	// { [componentType]: MarkerModel }
96	const inner = makeInner<Dictionary<MarkerModel>, SeriesModel>();
97	
98	abstract class MarkerModel<Opts extends MarkerOption = MarkerOption> extends ComponentModel<Opts> {
99	
100	    static type = 'marker';
101	    type = MarkerModel.type;
102	
103	    /**
104	     * If marker model is created by self from series
105	     */
106	    createdBySelf = false;
107	
108	    static readonly dependencies = ['series', 'grid', 'polar', 'geo'];
109	
110	    __hostSeries: SeriesModel;
111	
112	    private _data: SeriesData;
113	
114	    /**
115	     * @overrite
116	     */
117	    init(option: Opts, parentModel: Model, ecModel: GlobalModel) {
118	
119	        if (__DEV__) {
120	            if (this.type === 'marker') {
121	                throw new Error('Marker component is abstract component. Use markLine, markPoint, markArea instead.');
122	            }
123	        }
124	        this.mergeDefaultAndTheme(option, ecModel);
125	        this._mergeOption(option, ecModel, false, true);
126	    }
127	
128	    isAnimationEnabled(): boolean {
129	        if (env.node) {
130	            return false;
131	        }
132	
133	        const hostSeries = this.__hostSeries;
134	        return this.getShallow('animation') && hostSeries && hostSeries.isAnimationEnabled();
135	    }
136	
137	    /**
138	     * @overrite
139	     */
140	    mergeOption(newOpt: Opts, ecModel: GlobalModel) {
141	        this._mergeOption(newOpt, ecModel, false, false);
142	    }
143	
144	    _mergeOption(newOpt: Opts, ecModel: GlobalModel, createdBySelf?: boolean, isInit?: boolean) {
145	        const componentType = this.mainType;
146	        if (!createdBySelf) {
147	            ecModel.eachSeries(function (seriesModel) {
148	
149	                // mainType can be markPoint, markLine, markArea
150	                const markerOpt = seriesModel.get(
151	                    this.mainType as any, true
152	                ) as Opts;
153	
154	                let markerModel = inner(seriesModel)[componentType];
155	                if (!markerOpt || !markerOpt.data) {
156	                    inner(seriesModel)[componentType] = null;
157	                    return;
158	                }
159	                if (!markerModel) {
160	                    if (isInit) {
161	                        // Default label emphasis `position` and `show`
162	                        fillLabel(markerOpt);
163	                    }
164	                    zrUtil.each(markerOpt.data, function (item) {
165	                        // FIXME Overwrite fillLabel method ?
166	                        if (item instanceof Array) {
167	                            fillLabel(item[0]);
168	                            fillLabel(item[1]);
169	                        }
170	                        else {
171	                            fillLabel(item);
172	                        }
173	                    });
174	
175	                    markerModel = this.createMarkerModelFromSeries(
176	                        markerOpt, this, ecModel
