54	// Merge two ends option into one.
55	type MarkAreaMergedItemOption = Omit<MarkArea2DDataItemOption[number], 'coord'> & {
56	    coord: MarkArea2DDataItemOption[number]['coord'][]
57	    x0: number | string
58	    y0: number | string
59	    x1: number | string
60	    y1: number | string
61	};
62	
63	const markAreaTransform = function (
64	    seriesModel: SeriesModel,
65	    coordSys: CoordinateSystem,
66	    maModel: MarkAreaModel,
67	    item: MarkArea2DDataItemOption
68	): MarkAreaMergedItemOption {
69	    // item may be null
70	    const item0 = item[0];
71	    const item1 = item[1];
72	    if (!item0 || !item1) {
73	        return;
74	    }
75	
76	    const lt = markerHelper.dataTransform(seriesModel, item0);
77	    const rb = markerHelper.dataTransform(seriesModel, item1);
78	
79	    // FIXME make sure lt is less than rb
80	    const ltCoord = lt.coord;
81	    const rbCoord = rb.coord;
82	    ltCoord[0] = retrieve(ltCoord[0], -Infinity);
83	    ltCoord[1] = retrieve(ltCoord[1], -Infinity);
84	
85	    rbCoord[0] = retrieve(rbCoord[0], Infinity);
86	    rbCoord[1] = retrieve(rbCoord[1], Infinity);
87	
88	    // Merge option into one
89	    const result: MarkAreaMergedItemOption = mergeAll([{}, lt, rb]);
90	
91	    result.coord = [
92	        lt.coord, rb.coord
93	    ];
94	    result.x0 = lt.x;
95	    result.y0 = lt.y;
96	    result.x1 = rb.x;
97	    result.y1 = rb.y;
98	    return result;
99	};
100	
101	function isInfinity(val: ScaleDataValue) {
102	    return !isNaN(val as number) && !isFinite(val as number);
103	}
104	
105	// If a markArea has one dim
106	function ifMarkAreaHasOnlyDim(
107	    dimIndex: number,
108	    fromCoord: ScaleDataValue[],
109	    toCoord: ScaleDataValue[],
110	    coordSys: CoordinateSystem
111	) {
112	    const otherDimIndex = 1 - dimIndex;
113	    return isInfinity(fromCoord[otherDimIndex]) && isInfinity(toCoord[otherDimIndex]);
114	}
115	
116	function markAreaFilter(coordSys: CoordinateSystem, item: MarkAreaMergedItemOption) {
117	    const fromCoord = item.coord[0];
118	    const toCoord = item.coord[1];
119	    const item0 = {
120	        coord: fromCoord,
121	        x: item.x0,
122	        y: item.y0
123	    };
124	    const item1 = {
125	        coord: toCoord,
126	        x: item.x1,
127	        y: item.y1
128	    };
129	    if (isCoordinateSystemType<Cartesian2D>(coordSys, 'cartesian2d')) {
130	        // In case
131	        // {
132	        //  markArea: {
133	        //    data: [{ yAxis: 2 }]
134	        //  }
135	        // }
136	        if (
137	            fromCoord && toCoord
138	            && (ifMarkAreaHasOnlyDim(1, fromCoord, toCoord, coordSys)
139	            || ifMarkAreaHasOnlyDim(0, fromCoord, toCoord, coordSys))
140	        ) {
141	            return true;
142	        }
143	        // Directly returning true may also do the work,
144	        // because markArea will not be shown automatically
145	        // when it's not included in coordinate system.
146	        // But filtering ahead can avoid keeping rendering markArea
147	        // when there are too many of them.
148	        return markerHelper.zoneFilter(coordSys, item0, item1);
149	    }
150	    return markerHelper.dataFilter(coordSys, item0)
151	        || markerHelper.dataFilter(coordSys, item1);
152	}
