154	// dims can be ['x0', 'y0'], ['x1', 'y1'], ['x0', 'y1'], ['x1', 'y0']
155	function getSingleMarkerEndPoint(
156	    data: SeriesData<MarkAreaModel>,
157	    idx: number,
158	    dims: typeof dimPermutations[number],
159	    seriesModel: SeriesModel,
160	    api: ExtensionAPI
161	) {
162	    const coordSys = seriesModel.coordinateSystem;
163	    const itemModel = data.getItemModel<MarkAreaMergedItemOption>(idx);
164	
165	    let point;
166	    const xPx = numberUtil.parsePercent(itemModel.get(dims[0]), api.getWidth());
167	    const yPx = numberUtil.parsePercent(itemModel.get(dims[1]), api.getHeight());
168	    if (!isNaN(xPx) && !isNaN(yPx)) {
169	        point = [xPx, yPx];
170	    }
171	    else {
172	        // Chart like bar may have there own marker positioning logic
173	        if (seriesModel.getMarkerPosition) {
174	            // Consider the case that user input the right-bottom point first
175	            // Pick the larger x and y as 'x1' and 'y1'
176	            const pointValue0 = data.getValues(['x0', 'y0'], idx);
177	            const pointValue1 = data.getValues(['x1', 'y1'], idx);
178	            const clampPointValue0 = coordSys.clampData(pointValue0);
179	            const clampPointValue1 = coordSys.clampData(pointValue1);
180	            const pointValue = [];
181	            if (dims[0] === 'x0') {
182	                pointValue[0] = (clampPointValue0[0] > clampPointValue1[0]) ? pointValue1[0] : pointValue0[0];
183	            }
184	            else {
185	                pointValue[0] = (clampPointValue0[0] > clampPointValue1[0]) ? pointValue0[0] : pointValue1[0];
186	            }
187	            if (dims[1] === 'y0') {
188	                pointValue[1] = (clampPointValue0[1] > clampPointValue1[1]) ? pointValue1[1] : pointValue0[1];
189	            }
190	            else {
191	                pointValue[1] = (clampPointValue0[1] > clampPointValue1[1]) ? pointValue0[1] : pointValue1[1];
192	            }
193	            // Use the getMarkerPosition
194	            point = seriesModel.getMarkerPosition(
195	                pointValue, dims, true
196	            );
197	        }
198	        else {
199	            const x = data.get(dims[0], idx) as number;
200	            const y = data.get(dims[1], idx) as number;
201	            const pt = [x, y];
202	            coordSys.clampData && coordSys.clampData(pt, pt);
203	            point = coordSys.dataToPoint(pt, true);
204	        }
205	        if (isCoordinateSystemType<Cartesian2D>(coordSys, 'cartesian2d')) {
206	            // TODO: TYPE ts@4.1 may still infer it as Axis instead of Axis2D. Not sure if it's a bug
207	            const xAxis = coordSys.getAxis('x') as Axis2D;
208	            const yAxis = coordSys.getAxis('y') as Axis2D;
209	            const x = data.get(dims[0], idx) as number;
210	            const y = data.get(dims[1], idx) as number;
211	            if (isInfinity(x)) {
212	                point[0] = xAxis.toGlobalCoord(xAxis.getExtent()[dims[0] === 'x0' ? 0 : 1]);
213	            }
214	            else if (isInfinity(y)) {
215	                point[1] = yAxis.toGlobalCoord(yAxis.getExtent()[dims[1] === 'y0' ? 0 : 1]);
216	            }
217	        }
218	
219	        // Use x, y if has any
220	        if (!isNaN(xPx)) {
221	            point[0] = xPx;
222	        }
223	        if (!isNaN(yPx)) {
224	            point[1] = yPx;
225	        }
226	    }
227	
228	    return point;
229	}
