233	class MarkAreaView extends MarkerView {
234	
235	    static type = 'markArea';
236	    type = MarkAreaView.type;
237	
238	    markerGroupMap: HashMap<MarkAreaDrawGroup>;
239	
240	    updateTransform(markAreaModel: MarkAreaModel, ecModel: GlobalModel, api: ExtensionAPI) {
241	        ecModel.eachSeries(function (seriesModel) {
242	            const maModel = MarkerModel.getMarkerModelFromSeries(seriesModel, 'markArea') as MarkAreaModel;
243	            if (maModel) {
244	                const areaData = maModel.getData();
245	                areaData.each(function (idx) {
246	                    const points = map(dimPermutations, function (dim) {
247	                        return getSingleMarkerEndPoint(areaData, idx, dim, seriesModel, api);
248	                    });
249	                    // Layout
250	                    areaData.setItemLayout(idx, points);
251	                    const el = areaData.getItemGraphicEl(idx) as graphic.Polygon;
252	                    el.setShape('points', points);
253	                });
254	            }
255	        }, this);
256	    }
257	
258	    renderSeries(
259	        seriesModel: SeriesModel,
260	        maModel: MarkAreaModel,
261	        ecModel: GlobalModel,
262	        api: ExtensionAPI
263	    ) {
264	        const coordSys = seriesModel.coordinateSystem;
265	        const seriesId = seriesModel.id;
266	        const seriesData = seriesModel.getData();
267	
268	        const areaGroupMap = this.markerGroupMap;
269	        const polygonGroup = areaGroupMap.get(seriesId)
270	            || areaGroupMap.set(seriesId, {group: new graphic.Group()});
271	
272	        this.group.add(polygonGroup.group);
273	        this.markKeep(polygonGroup);
274	
275	        const areaData = createList(coordSys, seriesModel, maModel);
276	
277	        // Line data for tooltip and formatter
278	        maModel.setData(areaData);
279	
280	        // Update visual and layout of line
281	        areaData.each(function (idx) {
282	            // Layout
283	            const points = map(dimPermutations, function (dim) {
284	                return getSingleMarkerEndPoint(areaData, idx, dim, seriesModel, api);
285	            });
286	            const xAxisScale = coordSys.getAxis('x').scale;
287	            const yAxisScale = coordSys.getAxis('y').scale;
288	            const xAxisExtent = xAxisScale.getExtent();
289	            const yAxisExtent = yAxisScale.getExtent();
290	            const xPointExtent = [xAxisScale.parse(areaData.get('x0', idx)), xAxisScale.parse(areaData.get('x1', idx))];
291	            const yPointExtent = [yAxisScale.parse(areaData.get('y0', idx)), yAxisScale.parse(areaData.get('y1', idx))];
292	            numberUtil.asc(xPointExtent);
293	            numberUtil.asc(yPointExtent);
294	            const overlapped = !(xAxisExtent[0] > xPointExtent[1] || xAxisExtent[1] < xPointExtent[0]
295	                                || yAxisExtent[0] > yPointExtent[1] || yAxisExtent[1] < yPointExtent[0]);
296	            // If none of the area is inside coordSys, allClipped is set to be true
297	            // in layout so that label will not be displayed. See #12591
298	            const allClipped = !overlapped;
299	            areaData.setItemLayout(idx, {
300	                points: points,
301	                allClipped: allClipped
302	            });
303	
304	
305	            const style = areaData.getItemModel<MarkAreaMergedItemOption>(idx).getModel('itemStyle').getItemStyle();
306	            const color = getVisualFromData(seriesData, 'color') as ZRColor;
307	            if (!style.fill) {
308	                style.fill = color;
309	                if (isString(style.fill)) {
310	                    style.fill = colorUtil.modifyAlpha(style.fill, 0.4);
311	                }
312	            }
313	            if (!style.stroke) {
314	                style.stroke = color;
315	            }
316	            // Visual
317	            areaData.setItemVisual(idx, 'style', style);
318	        });
319	
320	
321	        areaData.diff(inner(polygonGroup).data)
322	            .add(function (idx) {
323	                const layout = areaData.getItemLayout(idx);
324	                if (!layout.allClipped) {
325	                    const polygon = new graphic.Polygon({
326	                        shape: {
327	                            points: layout.points
328	                        }
329	                    });
330	                    areaData.setItemGraphicEl(idx, polygon);
331	                    polygonGroup.group.add(polygon);
332	                }
333	            })
334	            .update(function (newIdx, oldIdx) {
335	                let polygon = inner(polygonGroup).data.getItemGraphicEl(oldIdx) as graphic.Polygon;
336	                const layout = areaData.getItemLayout(newIdx);
337	                if (!layout.allClipped) {
338	                    if (polygon) {
339	                        graphic.updateProps(polygon, {
340	                            shape: {
341	                                points: layout.points
342	                            }
343	                        }, maModel, newIdx);
344	                    }
345	                    else {
346	                        polygon = new graphic.Polygon({
347	                            shape: {
348	                                points: layout.points
349	                            }
350	                        });
351	                    }
352	                    areaData.setItemGraphicEl(newIdx, polygon);
353	                    polygonGroup.group.add(polygon);
354	                }
355	                else if (polygon) {
356	                    polygonGroup.group.remove(polygon);
357	                }
358	            })
359	            .remove(function (idx) {
360	                const polygon = inner(polygonGroup).data.getItemGraphicEl(idx);
361	                polygonGroup.group.remove(polygon);
362	            })
363	            .execute();
364	
365	        areaData.eachItemGraphicEl(function (polygon: graphic.Polygon, idx) {
366	            const itemModel = areaData.getItemModel<MarkAreaMergedItemOption>(idx);
367	            const style = areaData.getItemVisual(idx, 'style');
368	            polygon.useStyle(areaData.getItemVisual(idx, 'style'));
369	
370	            setLabelStyle(
371	                polygon, getLabelStatesModels(itemModel),
372	                {
373	                    labelFetcher: maModel,
374	                    labelDataIndex: idx,
375	                    defaultText: areaData.getName(idx) || '',
376	                    inheritColor: isString(style.fill)
377	                        ? colorUtil.modifyAlpha(style.fill, 1) : '#000'
378	                }
379	            );
380	
381	            setStatesStylesFromModel(polygon, itemModel);
382	
383	            toggleHoverEmphasis(polygon, null, null, itemModel.get(['emphasis', 'disabled']));
384	
385	            getECData(polygon).dataModel = maModel;
386	        });
387	
388	        inner(polygonGroup).data = areaData;
389	
390	        polygonGroup.group.silent = maModel.get('silent') || seriesModel.get('silent');
391	    }
392	}
