394	function createList(
395	    coordSys: CoordinateSystem,
396	    seriesModel: SeriesModel,
397	    maModel: MarkAreaModel
398	) {
399	
400	    let areaData: SeriesData<MarkAreaModel>;
401	    let dataDims: SeriesDimensionDefine[];
402	    const dims = ['x0', 'y0', 'x1', 'y1'];
403	    if (coordSys) {
404	        const coordDimsInfos: SeriesDimensionDefine[] = map(coordSys && coordSys.dimensions, function (coordDim) {
405	            const data = seriesModel.getData();
406	            const info = data.getDimensionInfo(
407	                data.mapDimension(coordDim)
408	            ) || {};
409	            // In map series data don't have lng and lat dimension. Fallback to same with coordSys
410	            return extend(extend({}, info), {
411	                name: coordDim,
412	                // DON'T use ordinalMeta to parse and collect ordinal.
413	                ordinalMeta: null
414	            });
415	        });
416	        dataDims = map(dims, (dim, idx) => ({
417	            name: dim,
418	            type: coordDimsInfos[idx % 2].type
419	        }));
420	        areaData = new SeriesData(dataDims, maModel);
421	    }
422	    else {
423	        dataDims = [{
424	            name: 'value',
425	            type: 'float'
426	        }];
427	        areaData = new SeriesData(dataDims, maModel);
428	    }
429	
430	    let optData = map(maModel.get('data'), curry(
431	        markAreaTransform, seriesModel, coordSys, maModel
432	    ));
433	    if (coordSys) {
434	        optData = filter(
435	            optData, curry(markAreaFilter, coordSys)
436	        );
437	    }
438	
439	    const dimValueGetter: markerHelper.MarkerDimValueGetter<MarkAreaMergedItemOption> = coordSys
440	        ? function (item, dimName, dataIndex, dimIndex) {
441	            // TODO should convert to ParsedValue?
442	            const rawVal = item.coord[Math.floor(dimIndex / 2)][dimIndex % 2];
443	            return parseDataValue(rawVal, dataDims[dimIndex]);
444	        }
445	        : function (item, dimName, dataIndex, dimIndex) {
446	            return parseDataValue(item.value, dataDims[dimIndex]);
447	        };
448	    areaData.initData(optData, null, dimValueGetter);
449	    areaData.hasItemOption = true;
450	    return areaData;
451	}
