263	class MarkLineView extends MarkerView {
264	
265	    static type = 'markLine';
266	    type = MarkLineView.type;
267	
268	    markerGroupMap: HashMap<LineDraw>;
269	
270	    updateTransform(markLineModel: MarkLineModel, ecModel: GlobalModel, api: ExtensionAPI) {
271	        ecModel.eachSeries(function (seriesModel) {
272	            const mlModel = MarkerModel.getMarkerModelFromSeries(seriesModel, 'markLine') as MarkLineModel;
273	            if (mlModel) {
274	                const mlData = mlModel.getData();
275	                const fromData = inner(mlModel).from;
276	                const toData = inner(mlModel).to;
277	                // Update visual and layout of from symbol and to symbol
278	                fromData.each(function (idx) {
279	                    updateSingleMarkerEndLayout(fromData, idx, true, seriesModel, api);
280	                    updateSingleMarkerEndLayout(toData, idx, false, seriesModel, api);
281	                });
282	                // Update layout of line
283	                mlData.each(function (idx) {
284	                    mlData.setItemLayout(idx, [
285	                        fromData.getItemLayout(idx),
286	                        toData.getItemLayout(idx)
287	                    ]);
288	                });
289	
290	                this.markerGroupMap.get(seriesModel.id).updateLayout();
291	
292	            }
293	        }, this);
294	    }
295	
296	    renderSeries(
297	        seriesModel: SeriesModel,
298	        mlModel: MarkLineModel,
299	        ecModel: GlobalModel,
300	        api: ExtensionAPI
301	    ) {
302	        const coordSys = seriesModel.coordinateSystem;
303	        const seriesId = seriesModel.id;
304	        const seriesData = seriesModel.getData();
305	
306	        const lineDrawMap = this.markerGroupMap;
307	        const lineDraw = lineDrawMap.get(seriesId)
308	            || lineDrawMap.set(seriesId, new LineDraw());
309	        this.group.add(lineDraw.group);
310	
311	        const mlData = createList(coordSys, seriesModel, mlModel);
312	
313	        const fromData = mlData.from;
314	        const toData = mlData.to;
315	        const lineData = mlData.line as SeriesData<MarkLineModel, LineDataVisual>;
316	
317	        inner(mlModel).from = fromData;
318	        inner(mlModel).to = toData;
319	        // Line data for tooltip and formatter
320	        mlModel.setData(lineData);
321	
322	        // TODO
323	        // Functionally, `symbolSize` & `symbolOffset` can also be 2D array now.
324	        // But the related logic and type definition are not finished yet.
325	        // Finish it if required
326	        let symbolType = mlModel.get('symbol');
327	        let symbolSize = mlModel.get('symbolSize');
328	        let symbolRotate = mlModel.get('symbolRotate');
329	        let symbolOffset = mlModel.get('symbolOffset');
330	        // TODO: support callback function like markPoint
331	        if (!isArray(symbolType)) {
332	            symbolType = [symbolType, symbolType];
333	        }
334	        if (!isArray(symbolSize)) {
335	            symbolSize = [symbolSize, symbolSize];
336	        }
337	        if (!isArray(symbolRotate)) {
338	            symbolRotate = [symbolRotate, symbolRotate];
339	        }
340	        if (!isArray(symbolOffset)) {
341	            symbolOffset = [symbolOffset, symbolOffset];
342	        }
343	
344	        // Update visual and layout of from symbol and to symbol
345	        mlData.from.each(function (idx) {
346	            updateDataVisualAndLayout(fromData, idx, true);
347	            updateDataVisualAndLayout(toData, idx, false);
348	        });
349	
350	        // Update visual and layout of line
351	        lineData.each(function (idx) {
352	            const lineStyle = lineData.getItemModel<MarkLineMergedItemOption>(idx)
353	                .getModel('lineStyle').getLineStyle();
354	            // lineData.setItemVisual(idx, {
355	            //     color: lineColor || fromData.getItemVisual(idx, 'color')
356	            // });
357	            lineData.setItemLayout(idx, [
358	                fromData.getItemLayout(idx),
359	                toData.getItemLayout(idx)
360	            ]);
361	
362	            if (lineStyle.stroke == null) {
363	                lineStyle.stroke = fromData.getItemVisual(idx, 'style').fill;
364	            }
365	
366	            lineData.setItemVisual(idx, {
367	                fromSymbolKeepAspect: fromData.getItemVisual(idx, 'symbolKeepAspect'),
368	                fromSymbolOffset: fromData.getItemVisual(idx, 'symbolOffset'),
369	                fromSymbolRotate: fromData.getItemVisual(idx, 'symbolRotate'),
370	                fromSymbolSize: fromData.getItemVisual(idx, 'symbolSize') as number,
371	                fromSymbol: fromData.getItemVisual(idx, 'symbol'),
372	                toSymbolKeepAspect: toData.getItemVisual(idx, 'symbolKeepAspect'),
373	                toSymbolOffset: toData.getItemVisual(idx, 'symbolOffset'),
374	                toSymbolRotate: toData.getItemVisual(idx, 'symbolRotate'),
375	                toSymbolSize: toData.getItemVisual(idx, 'symbolSize') as number,
376	                toSymbol: toData.getItemVisual(idx, 'symbol'),
377	                style: lineStyle
378	            });
379	        });
380	
381	        lineDraw.updateData(lineData);
382	
383	        // Set host model for tooltip
384	        // FIXME
385	        mlData.line.eachItemGraphicEl(function (el) {
386	            getECData(el).dataModel = mlModel;
387	
388	            el.traverse(function (child) {
389	                getECData(child).dataModel = mlModel;
390	            });
391	        });
392	
393	        function updateDataVisualAndLayout(
394	            data: SeriesData<MarkLineModel>,
395	            idx: number,
396	            isFrom: boolean
397	        ) {
398	            const itemModel = data.getItemModel<MarkLineMergedItemOption>(idx);
399	
400	            updateSingleMarkerEndLayout(
401	                data, idx, isFrom, seriesModel, api
402	            );
403	
404	            const style = itemModel.getModel('itemStyle').getItemStyle();
405	            if (style.fill == null) {
406	                style.fill = getVisualFromData(seriesData, 'color') as ColorString;
407	            }
408	
409	            data.setItemVisual(idx, {
410	                symbolKeepAspect: itemModel.get('symbolKeepAspect'),
411	                // `0` should be considered as a valid value, so use `retrieve2` instead of `||`
412	                symbolOffset: retrieve2(
413	                    itemModel.get('symbolOffset', true),
414	                    (symbolOffset as (string | number)[])[isFrom ? 0 : 1]
415	                ),
416	                symbolRotate: retrieve2(
417	                    itemModel.get('symbolRotate', true),
418	                    (symbolRotate as number[])[isFrom ? 0 : 1]
419	                ),
420	                // TODO: when 2d array is supported, it should ignore parent
421	                symbolSize: retrieve2(
422	                    itemModel.get('symbolSize'),
423	                    (symbolSize as number[])[isFrom ? 0 : 1]
424	                ),
425	                symbol: retrieve2(
426	                    itemModel.get('symbol', true),
427	                    (symbolType as string[])[isFrom ? 0 : 1]
428	                ),
429	                style
430	            });
431	        }
432	
433	        this.markKeep(lineDraw);
434	
435	        lineDraw.group.silent = mlModel.get('silent') || seriesModel.get('silent');
436	    }
437	}
