439	function createList(coordSys: CoordinateSystem, seriesModel: SeriesModel, mlModel: MarkLineModel) {
440	
441	    let coordDimsInfos: SeriesDimensionDefine[];
442	    if (coordSys) {
443	        coordDimsInfos = map(coordSys && coordSys.dimensions, function (coordDim) {
444	            const info = seriesModel.getData().getDimensionInfo(
445	                seriesModel.getData().mapDimension(coordDim)
446	            ) || {};
447	            // In map series data don't have lng and lat dimension. Fallback to same with coordSys
448	            return extend(extend({}, info), {
449	                name: coordDim,
450	                // DON'T use ordinalMeta to parse and collect ordinal.
451	                ordinalMeta: null
452	            });
453	        });
454	    }
455	    else {
456	        coordDimsInfos = [{
457	            name: 'value',
458	            type: 'float'
459	        }];
460	    }
461	
462	    const fromData = new SeriesData(coordDimsInfos, mlModel);
463	    const toData = new SeriesData(coordDimsInfos, mlModel);
464	    // No dimensions
465	    const lineData = new SeriesData([], mlModel);
466	
467	    let optData = map(mlModel.get('data'), curry(
468	        markLineTransform, seriesModel, coordSys, mlModel
469	    ));
470	    if (coordSys) {
471	        optData = filter(
472	            optData, curry(markLineFilter, coordSys)
473	        );
474	    }
475	
476	    const dimValueGetter = markerHelper.createMarkerDimValueGetter(!!coordSys, coordDimsInfos);
477	
478	    fromData.initData(
479	        map(optData, function (item) {
480	            return item[0];
481	        }),
482	        null,
483	        dimValueGetter
484	    );
485	    toData.initData(
486	        map(optData, function (item) {
487	            return item[1];
488	        }),
489	        null,
490	        dimValueGetter
491	    );
492	    lineData.initData(
493	        map(optData, function (item) {
494	            return item[2];
495	        })
496	    );
497	    lineData.hasItemOption = true;
498	
499	    return {
500	        from: fromData,
501	        to: toData,
502	        line: lineData
503	    };
504	}
