55	    /**
56	     * Get params for formatter
57	     */
58	    getDataParams(
59	        dataIndex: number,
60	        dataType?: SeriesDataType
61	    ): CallbackDataParams {
62	
63	        const data = this.getData(dataType);
64	        const rawValue = this.getRawValue(dataIndex, dataType);
65	        const rawDataIndex = data.getRawIndex(dataIndex);
66	        const name = data.getName(dataIndex);
67	        const itemOpt = data.getRawDataItem(dataIndex);
68	        const style = data.getItemVisual(dataIndex, 'style');
69	        const color = style && style[data.getItemVisual(dataIndex, 'drawType') || 'fill'] as ZRColor;
70	        const borderColor = style && style.stroke as ColorString;
71	        const mainType = this.mainType;
72	        const isSeries = mainType === 'series';
73	        const userOutput = data.userOutput && data.userOutput.get();
74	
75	        return {
76	            componentType: mainType,
77	            componentSubType: this.subType,
78	            componentIndex: this.componentIndex,
79	            seriesType: isSeries ? this.subType : null,
80	            seriesIndex: (this as any).seriesIndex,
81	            seriesId: isSeries ? this.id : null,
82	            seriesName: isSeries ? this.name : null,
83	            name: name,
84	            dataIndex: rawDataIndex,
85	            data: itemOpt,
86	            dataType: dataType,
87	            value: rawValue,
88	            color: color,
89	            borderColor: borderColor,
90	            dimensionNames: userOutput ? userOutput.fullDimensions : null,
91	            encode: userOutput ? userOutput.encode : null,
92	
93	            // Param name list for mapping `a`, `b`, `c`, `d`, `e`
94	            $vars: ['seriesName', 'name', 'value']
95	        };
96	    }
97	
98	    /**
99	     * Format label
100	     * @param dataIndex
101	     * @param status 'normal' by default
102	     * @param dataType
103	     * @param labelDimIndex Only used in some chart that
104	     *        use formatter in different dimensions, like radar.
105	     * @param formatter Formatter given outside.
106	     * @return return null/undefined if no formatter
107	     */
108	    getFormattedLabel(
109	        dataIndex: number,
110	        status?: DisplayState,
111	        dataType?: SeriesDataType,
112	        labelDimIndex?: number,
113	        formatter?: string | ((params: object) => string),
114	        extendParams?: {
115	            interpolatedValue: InterpolatableValue
116	        }
117	    ): string {
118	        status = status || 'normal';
119	        const data = this.getData(dataType);
120	
121	        const params = this.getDataParams(dataIndex, dataType);
122	
123	        if (extendParams) {
124	            params.value = extendParams.interpolatedValue;
125	        }
126	
127	        if (labelDimIndex != null && zrUtil.isArray(params.value)) {
128	            params.value = params.value[labelDimIndex];
129	        }
130	
131	        if (!formatter) {
132	            const itemModel = data.getItemModel(dataIndex);
133	            // @ts-ignore
134	            formatter = itemModel.get(status === 'normal'
135	                ? ['label', 'formatter']
136	                : [status, 'label', 'formatter']
137	            );
138	        }
139	
140	        if (zrUtil.isFunction(formatter)) {
141	            params.status = status;
142	            params.dimensionIndex = labelDimIndex;
143	            return formatter(params);
144	        }
145	        else if (zrUtil.isString(formatter)) {
146	            const str = formatTpl(formatter, params);
147	
148	            // Support 'aaa{@[3]}bbb{@product}ccc'.
149	            // Do not support '}' in dim name util have to.
150	            return str.replace(DIMENSION_LABEL_REG, function (origin, dimStr: string) {
151	                const len = dimStr.length;
152	
153	                let dimLoose: DimensionLoose = dimStr;
154	                if (dimLoose.charAt(0) === '[' && dimLoose.charAt(len - 1) === ']') {
155	                    dimLoose = +dimLoose.slice(1, len - 1); // Also support: '[]' => 0
156	                    if (__DEV__) {
157	                        if (isNaN(dimLoose)) {
158	                            error(`Invalide label formatter: @${dimStr}, only support @[0], @[1], @[2], ...`);
159	                        }
160	                    }
161	                }
162	
163	                let val = retrieveRawValue(data, dataIndex, dimLoose) as OptionDataValue;
164	
165	                if (extendParams && zrUtil.isArray(extendParams.interpolatedValue)) {
166	                    const dimIndex = data.getDimensionIndex(dimLoose);
167	                    if (dimIndex >= 0) {
168	                        val = extendParams.interpolatedValue[dimIndex];
169	                    }
170	                }
171	
172	                return val != null ? val + '' : '';
173	            });
174	        }
175	    }
