        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    function makeCollector(collected: CallbackDataParams[]) {
        return function (params: CallbackDataParams): string {
            collected.push(params);
            return 'formatted';
        };
    }

    it('label formatter params should contain the host series info', function () {
        const markPointParams: CallbackDataParams[] = [];
        const markLineParams: CallbackDataParams[] = [];
        const markAreaParams: CallbackDataParams[] = [];

        chart.setOption({
            xAxis: {
                type: 'category',
                data: ['A', 'B', 'C']
            },
            yAxis: {},
            series: [{
                id: 'my_series_id',
                name: 'my_series_name',
                type: 'bar',
                data: [10, 20, 30],
                markPoint: {
                    label: {
                        formatter: makeCollector(markPointParams)
                    },
                    data: [{
                        name: 'mark_point_name',
                        xAxis: 'B',
                        yAxis: 20
                    }]
                },
                markLine: {
                    label: {
                        formatter: makeCollector(markLineParams)
                    },
                    data: [{
                        name: 'mark_line_name',
                        yAxis: 15
                    }]
                },
                markArea: {
                    label: {
                        formatter: makeCollector(markAreaParams)
                    },
                    data: [[{
                        name: 'mark_area_name',
                        xAxis: 'A'
                    }, {
                        xAxis: 'C'
                    }]]
                }
            }]
        });

        const cases: [string, CallbackDataParams[], string][] = [
            ['markPoint', markPointParams, 'mark_point_name'],
            ['markLine', markLineParams, 'mark_line_name'],
            ['markArea', markAreaParams, 'mark_area_name']
        ];

        for (let i = 0; i < cases.length; i++) {
            const componentType = cases[i][0];
            const collected = cases[i][1];
            const name = cases[i][2];

            expect(collected.length).toBeGreaterThan(0);

            const params = collected[0];
            expect(params.componentType).toEqual(componentType);
            expect(params.seriesId).toEqual('my_series_id');
            expect(params.seriesName).toEqual('my_series_name');
            expect(params.seriesType).toEqual('bar');
            expect(params.seriesIndex).toEqual(0);
            expect(params.name).toEqual(name);
            expect(params.dataIndex).toEqual(0);
            expect(params.data).toBeTruthy();
            expect('value' in params).toEqual(true);
        }
    });

    it('should not change the default label text when no formatter is given', function () {
        chart.setOption({
            xAxis: {
                type: 'category',
                data: ['A', 'B', 'C']
            },
            yAxis: {},
            series: [{
                name: 'my_series_name',
                type: 'bar',
                data: [10, 20, 30],
                markPoint: {
                    data: [{
                        name: 'mark_point_name',
                        xAxis: 'B',
                        yAxis: 20
                    }]
                },
                markLine: {
                    data: [{
                        name: 'mark_line_name',
                        yAxis: 15
                    }]
                },
                markArea: {
                    data: [[{
                        name: 'mark_area_name',
                        xAxis: 'A'
                    }, {
                        xAxis: 'C'
                    }]]
                }
            }]
        });

        const texts: string[] = [];
        chart.getZr().storage.traverse(function (el) {
            const textContent = el.getTextContent && el.getTextContent();
            if (textContent && textContent.style && textContent.style.text) {
                texts.push(textContent.style.text as string);
            }
        }, true);

        expect(texts.indexOf('mark_point_name')).toBeGreaterThanOrEqual(0);
        expect(texts.indexOf('mark_line_name')).toBeGreaterThanOrEqual(0);
        expect(texts.indexOf('mark_area_name')).toBeGreaterThanOrEqual(0);
    });
});

