import { createChart, removeChart, getECModel } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import { EChartsOption } from '../../../../../src/export/option';
import MarkerModel from '../../../../../src/component/marker/MarkerModel';
import MarkLineModel from '../../../../../src/component/marker/MarkLineModel';
import { LineDataVisual } from '../../../../../src/visual/commonVisualTypes';
import SeriesData from '../../../../../src/data/SeriesData';

describe('component/marker/markLine', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    function getMarkLineData(): SeriesData<MarkLineModel, LineDataVisual> {
        const seriesModel = getECModel(chart).getSeriesByIndex(0);
        const mlModel = MarkerModel.getMarkerModelFromSeries(seriesModel, 'markLine') as MarkLineModel;
        return mlModel.getData() as unknown as SeriesData<MarkLineModel, LineDataVisual>;
    }

    it('symbolOffset can be a 2d array for the two end symbols', function () {
        // Should also be valid for TypeScript.
        const option: EChartsOption = {
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'line',
                data: [10, 20, 30],
                markLine: {
                    symbolOffset: [[10, 20], ['30%', -40]],
                    data: [{ yAxis: 20 }]
                }
            }]
        };
        chart.setOption(option);

        const lineData = getMarkLineData();
        expect(lineData.getItemVisual(0, 'fromSymbolOffset')).toEqual([10, 20]);
        expect(lineData.getItemVisual(0, 'toSymbolOffset')).toEqual(['30%', -40]);
    });

    it('symbolOffset can still be a single offset shared by the two end symbols', function () {
        const option: EChartsOption = {
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'line',
                data: [10, 20, 30],
                markLine: {
                    symbolOffset: 5,
                    data: [{ yAxis: 20 }]
                }
            }]
        };
        chart.setOption(option);

        const lineData = getMarkLineData();
        expect(lineData.getItemVisual(0, 'fromSymbolOffset')).toEqual(5);
        expect(lineData.getItemVisual(0, 'toSymbolOffset')).toEqual(5);
    });
});

content.text:
Both requirements are implemented, verified, and committed.

**1. `marker-formatter-series-context`** (commit `b5a702d`) — I fetched the actual upstream PR #19898 diff and matched it: the fix is a `getDataParams` override on the shared base model rather than in the three views (all marker label formatters route through `DataFormatMixin.getDataParams` on the per-series marker model, whose `mainType` is `markPoint`/`markLine`/`markArea`, so the mixin nulled out `seriesId`/`seriesName`/`seriesType`).

- `/workspace/src/component/marker/MarkerModel.ts` — added
```ts
getDataParams(dataIndex: number, dataType?: SeriesDataType): CallbackDataParams {
    const params = DataFormatMixin.prototype.getDataParams.call(this, dataIndex, dataType);
    const hostSeries = this.__hostSeries;
    if (hostSeries) {
        params.seriesId = hostSeries.id;
        params.seriesName = hostSeries.name;
        params.seriesType = hostSeries.subType;
    }
    return params;
}
```
plus the `CallbackDataParams, SeriesDataType` imports and the missing trailing newline (also part of upstream). Because `zrUtil.mixin` does not override existing prototype members, the explicit `DataFormatMixin.prototype.getDataParams.call` is required. `seriesIndex`, `name`, `dataIndex`, `data`, `value` already flowed through.
- `/workspace/test/ut/spec/component/marker/formatter.test.ts` — new test: asserts formatter params for all three marker types carry `componentType`, `seriesId`, `seriesName`, `seriesType`, `seriesIndex`, `name`, `dataIndex`, `data`, `value`; second case asserts default label text is unchanged when no formatter is set. I confirmed the first test fails (`seriesId` → `null`) with the fix disabled.

Note: upstream also rewrote `/workspace/test/markPoint.html` (a manual visual test) in that PR — outside my cluster scope, so I left it untouched.

**2. `markline-symboloffset-2d-array`** (commit `45e1b93`) — matches upstream PR #20491 exactly (one line):

- `/workspace/src/component/marker/MarkLineModel.ts` — `MarkLineOption.symbolOffset?: number | string | (number | string)[] | (number | string)[][]`. Runtime already handled the 2D form (`MarkLineView` indexes the array per end), so no runtime change.
- `/workspace/test/ut/spec/component/marker/markLine.test.ts` — new test: `symbolOffset: [[10, 20], ['30%', -40]]` produces `fromSymbolOffset === [10, 20]` / `toSymbolOffset === ['30%', -40]`, and the scalar form still applies to both ends. `test/types/**` is outside my file scope, so instead I type-checked a scratch fixture (`/tmp/tscheck/symbolOffset.ts`) against `src/export/option`: it errors with `Type 'number[][]' is not assignable to type 'string | number | (string | number)[]'` before the change and is clean after, with the simple forms still valid.

Verification: full unit suite `53 suites / 306 tests` pass; `npx tsc --noEmit` is clean; `npx eslint` on my files reports only the pre-existing `Opts` unused-var warning on the declaration-merging line.

`git status --porcelain` leftovers are all from other clusters (nothing under `src/component/marker/**` or `test/ut/spec/component/marker/**`).
